# Rebuild organic_verification + search_log, and add the new owner-action artifacts.
import csv, os

D = os.path.join("docs", "mogra-organics-research-2026-10-02")

def w(name, header, rows):
    p = os.path.join(D, name)
    n = len(header); bad = 0; fixed = []
    for i, r in enumerate(rows, 1):
        if len(r) != n:
            bad += 1
            print(f"  !! {name} row {i}: {len(r)} cols expected {n}")
            r = (list(r) + [""] * n)[:n]
        fixed.append(r)
    with open(p, "w", newline="", encoding="utf-8") as f:
        cw = csv.writer(f, quoting=csv.QUOTE_MINIMAL); cw.writerow(header)
        for r in fixed: cw.writerow(r)
    print(f"{name}: {len(fixed)} data rows, {bad} mismatches")

